      av_frame_free(&decoded);
      av_frame_free(&nv12);
      return BadVideo;
    }

    sws_scale(sws, decoded->data, decoded->linesize, 0, decoded->height,
              nv12->data, nv12->linesize);
    sws_freeContext(sws);
    av_frame_free(&decoded);
    m_frame = nv12;
