  // start playback
  nextFrame();
} else {
  m_wallpaper = nullptr;
}
return error;

input.new_string:
m_wallpaper = std::make_unique<Wallpaper>();
m_wallpaperPlaying = true;
m_isFirstAnimationFrame = true;
m_useTransitions = false;
m_requiredTransitionShaderProgram = {};
m_transitionName = "none";
m_currentImgPath = img_path;
if (transition.has_value()) {
  auto trans = *transition;
  m_useTransitions = true;
  if (m_transitionShaderPrograms.contains(trans)) {
    m_requiredTransitionShaderProgram = m_transitionShaderPrograms[trans];
    m_transitionName = trans;
  } else {
    // just ignore
    m_useTransitions = false;
    m_transitionName = "none (unknown: " + trans + ")";
  }
}
auto error = m_wallpaper->bind(img_path, m_daemon.m_vaDisplay,
                               m_daemon.m_hardwareAccelerationBackend);
if (error == Success) {
  double fps = 1e9 / static_cast<double>(m_wallpaper->m_frameDuration.count());
  std::cerr << "[yin] " << m_name
            << ": applying wallpaper '" << std::filesystem::path(img_path).filename().string()
            << "' | transition=" << m_transitionName
            << " | fps=" << static_cast<int>(fps + 0.5)
            << " | single_frame=" << (m_wallpaper->m_isSingleFrame ? "yes" : "no")
            << "\n";
  m_nextVideoFrame = std::chrono::steady_clock::now();
  m_wallpaperID++;
  // write to history file
  auto file_path = historyFile();
  std::ofstream cachefile(file_path);
  cachefile << img_path;
  cachefile.close();
  // start playback
  nextFrame();
} else {
  std::cerr << "[yin] " << m_name << ": failed to bind '" << img_path << "' (error=" << error << ")\n";
  m_wallpaper = nullptr;
}
return error;

