#include <iomanip>
#include <iostream>

inline std::ostream &yin_log(std::ostream &os = std::cerr) {
  auto now = std::chrono::system_clock::now();
  auto t = std::chrono::system_clock::to_time_t(now);
  std::tm tm{};
  localtime_r(&t, &tm);
  return os << std::put_time(&tm, "%Y-%m-%d %H:%M:%S") << " [yin] ";
}

