  if (file.is_open()) {
    std::string first_line;
    if (!std::getline(file, first_line))
      return NoHistory;
    if (!std::filesystem::exists(first_line))
      return BadVideo;
    return setWallpaper(first_line, std::nullopt);
  }
  return NoHistory;
