    copy.srcDevice = reinterpret_cast<CUdeviceptr>(frame->data[1]);
    copy.srcPitch = frame->linesize[1];
    copy.dstMemoryType = CU_MEMORYTYPE_HOST; // <-- fixed
    copy.dstHost = m_hostUV.data();
    copy.dstPitch = width;
    copy.WidthInBytes = width;
    copy.Height = height / 2;
